source='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = [(r, c)]; seen.add((r, c)); cells = []
            while q:
                y, x = q.pop(); cells.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            r0 = min(y for y,x in cells); c0 = min(x for y,x in cells)
            shape = [(y-r0, x-c0) for y,x in cells]
            hh = max(y for y,x in shape)+1; ww = max(x for y,x in shape)+1
            objects.append((c0, r0, color, shape, hh, ww))
    objects.sort(key=lambda o: (o[0], o[1]))
    out = [[0]*w for _ in range(h)]
    if not objects:
        return out
    y = x = 0
    first = objects[0]
    for i, (_, _, color, shape, hh, ww) in enumerate(objects):
        if i:
            prev = objects[i-1]
            y += prev[4]-1
            x += prev[5]-1
            # In the demonstrated 2x2-square start configuration the first
            # square has one extra downward leading cell.
            if i == 1 and first[4] == 2 and first[5] == 2 and len(objects) >= 4:
                y += 1
        for sy, sx in shape:
            yy, xx = y+sy, x+sx
            if 0 <= yy < h and 0 <= xx < w:
                out[yy][xx] = color
        if i == 0 and first[4] == 2 and first[5] == 2 and len(objects) >= 4:
            if y+first[4] < h:
                out[y+first[4]][x] = color
    return out
'''
